package org.synqoria.scheduling;import java.util.*;
public class AppointmentAuditChainTest{public static void main(String[]a){int n=0;var first=AppointmentAuditChain.append(null,"a".repeat(64),"actor_1234");var second=AppointmentAuditChain.append(first,"b".repeat(64),"actor_1234");check(first.sequence()==1);n++;check(second.sequence()==2);n++;check(second.previousDigest().equals(first.digest()));n++;check(AppointmentAuditChain.verify(List.of(first,second)));n++;check(!AppointmentAuditChain.verify(List.of(second)));n++;check(!AppointmentAuditChain.verify(List.of(first,first)));n++;var forged=new AppointmentAuditChain.Entry(2,first.digest(),"c".repeat(64),"actor_1234",second.digest());check(!AppointmentAuditChain.verify(List.of(first,forged)));n++;check(!AppointmentAuditChain.verify(null));n++;try{AppointmentAuditChain.append(null,"x","actor_1234");throw new AssertionError();}catch(IllegalArgumentException expected){n++;}System.out.println("PASS "+n+" audit chain assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
